    if (!isCacheEnabled()) {
        return;
    }

    // Check if the data is null
    if (data == null) {
        return;
    }

    // Check if the data is already in the cache
    if (cache.containsKey(data.getKey())) {
        // If the data is already in the cache, merge the new data with the existing data
        METRICS existingData = cache.get(data.getKey());
        existingData.merge(data);
        cache.put(data.getKey(), existingData);
    } else {
        // If the data is not in the cache, add it to the cache
        cache.put(data.getKey(), data);
    }
}
